    weeksForPromotion(level) {
      let i = 6;
      if (level <= 2) {
        i = 3;
      } else if (level >= 3 && level <= 4) {
        i = 5;
      } else if (level < 5 || level > 6) {
        i = level >= 7 ? 8 : 0;
      }
      let workYearLengthWeeks = i * Constants.Time.INSTANCE.getWorkYearLengthWeeks();
      if (GameStateManager.INSTANCE.getPersonState().hasPerk(Perk.growthMindset)) {
        let growthMindsetPromotionBoost = Perk.INSTANCE.getGrowthMindsetPromotionBoost();
        let d = workYearLengthWeeks;
        Double.isNaN(d);
        workYearLengthWeeks = JMath.toInt(growthMindsetPromotionBoost * d);
      }
      if (GameStateManager.INSTANCE.getPersonState().hasTrait(Trait.humble)) {
        let humblePromotionBoost = Trait.INSTANCE.getHumblePromotionBoost();
        let d2 = workYearLengthWeeks;
        Double.isNaN(d2);
        workYearLengthWeeks = JMath.toInt(humblePromotionBoost * d2);
      }
      if (!GameStateManager.INSTANCE.getPersonState().hasTrait(Trait.lazy)) {
        return workYearLengthWeeks;
      }
      let lazyPromotionModifier = Trait.INSTANCE.getLazyPromotionModifier();
      let d3 = workYearLengthWeeks;
      Double.isNaN(d3);
      return JMath.toInt(lazyPromotionModifier * d3);
    }
