  var rnd3 = (a, b) => a + Math.random() * (b - a);
  var pick3 = (xs) => xs[Math.floor(Math.random() * xs.length)];
  var clamp2 = (n, a, b) => Math.max(a, Math.min(b, n));
  var money3 = (n) => ExtensionsKt.numberDisplayString(BigInteger.valueOf(Math.round(n)), true);
  var earn2 = (p, n, label3 = null) => MoneyState.updateMoney$default(p.getMoneyState(), BigInteger.valueOf(Math.round(n)), MoneyUpdateType.workIncome, label3, null, 8, null);
