          const tr = (kd.traits ?? Youth.kidTraits(kd)).map((k) => Youth.trait(k).title);
          if (tr.length) rows.push([t.getAgeInYears() >= 18 ? "Grew up to be" : "Growing up to be", tr.join(", ")]);
