      out.push(link(img3("icon_vamp_identity"), "The Masquerade", `Rumours ${Math.round(s2.suspicion)} \xB7 the Hunt ${Math.round(r.hunt)}${r.cover ? " \xB7 cover story in place" : ""}`, "vampire-masquerade"));
      out.push(link(img3("icon_vamp_court"), "Court", `${Reborn.standingTitle(p)} in ${Court.cityName(p)} \xB7 ${r.owed} favour${r.owed === 1 ? "" : "s"} owed to you${r.task ? " \xB7 on a task" : ""}`, "vampire-court"));
      out.push(link(img3("menu_coffin"), "Your Lair", `${r.lair.length} of ${LAIR.length} upgrades${r.vault ? ` \xB7 ${money16(r.vault)} in the Vault` : ""}`, "vampire-lair"));
      out.push(link(img3(line.image), "Bloodline", `${line.title} \xB7 sire ${r.sireName || "unknown"} \xB7 ${Bonds2.childer(p).length} childer \xB7 ${Object.keys(r.vintages).length} vintages`, "vampire-bloodline"));
      const bond5 = Vampire.bondedPartner(p);
